query siteWifiRadioProfileList ( $accountId:ID! $wifiRadioProfileListInput:WifiRadioProfileListInput!) {
	site ( accountId:$accountId ) {
		wifiRadioProfileList ( input:$wifiRadioProfileListInput  )  {
			wifiRadioProfiles {
				id
				site {
					id
					name
				}
				band24 {
					band
					standard
					channelWidth
					dfsEnabled
					channel
				}
				band5 {
					band
					standard
					channelWidth
					dfsEnabled
					channel
				}
			}
			pageInfo {
				total
			}
		}
	}	
}
